-- Card catalog: base spirit art, card seasons, and the fixed cards of each season.
-- Season content is loaded from seasons/<id>/seed.sql (generated by cmd/seasongen).

-- +goose Up
CREATE TABLE card_templates (
    id       text PRIMARY KEY,          -- spirit id, e.g. 'gaja-calf' (matches the art asset)
    name     text NOT NULL,
    name_si  text NOT NULL,
    element  text NOT NULL,
    rarity   text NOT NULL,
    lore     text NOT NULL DEFAULT ''
);

-- A card season is a fixed set of cards (e.g. 1,500) that packs draw from.
-- Not the same as the weekly leaderboard season.
CREATE TABLE card_seasons (
    id          text PRIMARY KEY,       -- 's1'
    name        text NOT NULL,
    seed        bigint NOT NULL,
    card_count  integer NOT NULL,
    starts_at   timestamptz,
    ends_at     timestamptz
);

CREATE TABLE season_cards (
    id              text PRIMARY KEY,   -- 's1-0042'
    card_season_id  text NOT NULL REFERENCES card_seasons(id),
    set_no          integer NOT NULL,
    template_id     text NOT NULL REFERENCES card_templates(id),
    rarity          text NOT NULL,
    name            text NOT NULL,      -- 'Brightly Moonlit Gaja Calf of Kandy'
    title           text NOT NULL,      -- 'Gaja Calf'
    epithet         text NOT NULL,      -- 'Brightly Moonlit · of Kandy'
    traits          jsonb NOT NULL,     -- prefix, intensity, adverb, suffix, pattern, palette, stamp, foil, visual
    score           integer NOT NULL,
    drop_weight     double precision NOT NULL,  -- relative chance within its rarity
    max_copies      integer,            -- NULL = unlimited
    minted          integer NOT NULL DEFAULT 0, -- copies pulled so far
    art_seed        bigint NOT NULL,
    UNIQUE (card_season_id, set_no),
    CHECK (max_copies IS NULL OR minted <= max_copies)
);

CREATE INDEX season_cards_pull_idx ON season_cards (card_season_id, rarity);

-- +goose Down
DROP TABLE season_cards;
DROP TABLE card_seasons;
DROP TABLE card_templates;
